templates.template:
/* Resource Cards */
.xfdevs__resource__card {
    background: #ebebeb;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
    transition: all 0.3s;
    height: 100%;
    display: flex;
    flex-direction: column;
    max-width: 384px;
}


/* Card padding */
.xfdevs__resource__card_padding {
    padding: 1rem;
}

/* Image container */
.xfdevs__resource__image_container {
    position: relative;
    border-radius: 16px;
    overflow: hidden;
	box-shadow: 0px 11px 20px 0px rgba(0, 0, 0, 0.12);
}

.xfdevs__resource__image_wrapper {
    aspect-ratio: 16/9;
    position: relative;
    overflow: hidden;
    border-radius: 16px;
}

.xfdevs__resource__card_image {
    position: relative;
    height: 12rem;
    overflow: hidden;
}

.xfdevs__resource__image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s;
}

.xfdevs__resource__card:hover .xfdevs__resource__image {
    transform: scale(1.05);
}

/* Overlay */
.xfdevs__resource__overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(to top, #FFA2A2 0%, transparent 100%);
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
}

.xfdevs__resource__title {
    color: white;
    font-size: 1.5rem;
    font-weight: bold;
    margin-bottom: 0.5rem;
}

.xfdevs__resource__location {
    display: flex;
    align-items: center;
	justify-content: space-between;
    color: rgba(255, 255, 255, 0.8);
    font-size: 0.875rem;
}

.xfdevs__resource__location_icon {
    width: 1rem;
    height: 1rem;
    margin-right: 0.25rem;
}

.xfdevs__resource__image_overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
}

.xfdevs__resource__menu_button {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    width: 2rem;
    height: 2rem;
    background: rgba(0, 0, 0, 0.2);
    border: none;
    border-radius: 0.25rem;
    color: white;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
}

.xfdevs__resource__menu_button:hover {
    background: rgba(0, 0, 0, 0.4);
}

.xfdevs__resource__menu_icon {
    width: 1rem;
    height: 1rem;
}

.xfdevs__resource__card_overlay_content {
    position: absolute;
    bottom: 1rem;
    left: 1rem;
    right: 5rem;
}

.xfdevs__resource__card_title {
    color: white;
    font-weight: bold;
    font-size: 1.125rem;
    line-height: 1.25;
    margin-bottom: 0.25rem;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.xfdevs__resource__card_category {
    color: rgba(255, 255, 255, 0.8);
    font-size: 0.875rem;
}

.xfdevs__resource__download_button {
    position: absolute;
    bottom: 1rem;
    right: 1rem;
    background: rgba(255, 255, 255, 0.2);
    border: 1px solid rgba(255, 255, 255, 0.3);
    color: white;
    padding: 0.5rem 0.75rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    cursor: pointer;
    transition: all 0.2s;
    backdrop-filter: blur(4px);
}

.xfdevs__resource__download_button:hover {
    background: rgba(255, 255, 255, 0.3);
}

.xfdevs__resource__category {
	display: flex;
	align-items: center;
	gap: .2rem;
}

/* Download button (new style) */

.xfdevs__resource__download_btn {
    background-color: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(4px);
    color: white;
    border: none;
    border-radius: 9999px;
    padding: 0.5rem 1.5rem;
    cursor: pointer;
    font-size: 0.875rem;
    font-weight: 500;
    transition: background-color 0.2s;
}

.xfdevs__resource__download_btn:hover {
    background-color: rgba(255, 255, 255, 0.3);
}

/* More options button (new style) */
.xfdevs__resource__more_btn {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(4px);
    border: none;
    border-radius: 50%;
    padding: 0.5rem;
    cursor: pointer;
    color: white;
    transition: background-color 0.2s;
}

.xfdevs__resource__more_btn:hover {
    background-color: rgba(0, 0, 0, 0.3);
}

.xfdevs__resource__more_icon {
    width: 1.25rem;
    height: 1.25rem;
}

/* Details section (new style) */
.xfdevs__resource__details {
    padding: 1.25rem;
}

.xfdevs__resource__header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1.5rem;
}

.xfdevs__resource__info {
    display: flex;
    flex-direction: column;
}

.xfdevs__resource__difficulty {
    font-size: 1.125rem;
    font-weight: bold;
    color: #1f2937;
    margin-bottom: 0.25rem;
}

.xfdevs__resource__creator {
    font-size: 0.875rem;
    color: #6b7280;
}

.xfdevs__resource__chart {
    display: flex;
    align-items: center;
    justify-content: center;
}

.xfdevs__resource__card_content {
    padding: 1rem;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.xfdevs__resource__card_meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.xfdevs__resource__price_badge {
    padding: 0.25rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.75rem;
    font-weight: 500;
}

.xfdevs__resource__price_badge__free {
    background: #f3f4f6;
    color: #374151;
}

.xfdevs__resource__price_badge__paid {
    background: #dbeafe;
    color: #1e40af;
}

.xfdevs__resource__rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

.xfdevs__resource__star {
    width: 0.75rem;
    height: 0.75rem;
    fill: #fbbf24;
    color: #fbbf24;
}

.xfdevs__resource__author {
    color: #6b7280;
    font-size: 0.875rem;
}

.xfdevs__resource__author span {
    color: #111827;
    font-weight: 500;
}
